# Lightweight original illustrated postcards for offline use. These are deliberately
# graphic memory cards, not photographs, and avoid third-party image licensing/watermarks.
def svg_for(place, index, vis):
    c1,c2=region_colors[place['region']]
    kind=vis['kind']
    motifs={
      'snow':'❄','food':'食','nature':'山','festival':'祭','culture':'文','history':'史','craft':'工','coast':'海',
      'garden':'庭','science':'科','shrine':'⛩','onsen':'湯','railway':'鉄','temple':'寺','city':'都','modern':'新','port':'港',
      'mountain':'山','lake':'湖','tea':'茶','castle':'城','industry':'産','tradition':'和','nightlife':'夜','deer':'鹿','pilgrimage':'道',
      'dunes':'砂','myth':'神','performance':'舞','folktale':'話','peace':'和','island':'島','sea':'海','cycling':'輪','river':'川','volcano':'火'
    }
    mark=motifs.get(kind,'旅')
    # Use only broadly supported text; if emoji is missing, the large Japanese mark remains.
    title=html.escape(vis['title'])
    pref=html.escape(place['prefecture_en'])
    jp=html.escape(place['prefecture_jp'])
    return f'''<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 640 400" role="img" aria-label="{pref} illustrated postcard">
<defs><linearGradient id="g" x1="0" y1="0" x2="1" y2="1"><stop stop-color="{c1}"/><stop offset="1" stop-color="{c2}"/></linearGradient><pattern id="p" width="32" height="32" patternUnits="userSpaceOnUse"><circle cx="3" cy="3" r="2" fill="#fff" opacity=".2"/></pattern></defs>
<rect width="640" height="400" rx="32" fill="url(#g)"/><rect width="640" height="400" rx="32" fill="url(#p)"/>
<circle cx="520" cy="92" r="86" fill="#fff" opacity=".16"/><circle cx="100" cy="330" r="130" fill="#fff" opacity=".10"/>
<path d="M0 308 Q110 250 210 302 T430 288 T640 300 V400 H0Z" fill="#fff" opacity=".18"/>
<text x="54" y="82" font-size="30" font-family="sans-serif" fill="#fff" font-weight="700">{pref}</text>
<text x="54" y="128" font-size="28" font-family="sans-serif" fill="#fff" opacity=".9">{jp}</text>
<text x="320" y="250" text-anchor="middle" font-size="118" font-family="sans-serif" fill="#fff" font-weight="800" opacity=".94">{mark}</text>
<text x="320" y="345" text-anchor="middle" font-size="28" font-family="sans-serif" fill="#fff" font-weight="700">{title}</text>
</svg>'''

for place in places:
    for i,vis in enumerate(place['visuals'],1):
        (IMG/f"{place['id']}-{i}.svg").write_text(svg_for(place,i,vis),encoding='utf-8')
print(f'wrote {len(places)} places, {len(places)*3} postcards')
